[{"ref_id":0,"title":"Physical data: sprints, speed, and distance: Definitions used by Match Desk","terms":"Physical data: sprints, speed, and distance","content":"- A sprint is running faster than 25.2 km/h for at least one second.\n- Top speed is the fastest a player reached during a sprint; elite players reach 33 to 36 km/h.\n- Distance covered is the total ground a player has run. A typical outfield player covers 10 to 12 km in a match; midfielders usually cover the most."},{"ref_id":1,"title":"The low block and the counter-attack: Counter-attacking","terms":"The low block and the counter-attack","content":"Teams that sit in a low block aim to break quickly when they win the ball, with forwards who run into the space the opponent leaves behind. The danger is in the transition, not in long spells of possession."},{"ref_id":2,"title":"Field tilt: Why it matters","terms":"Field tilt","content":"Possession counts every pass, including safe ones in a team's own half. Field tilt only counts the passes that put the opponent under pressure, so it tells you which side is pinning the other back. A team can have less of the ball and still dominate territory, which is common for direct and pressing teams."},{"ref_id":3,"title":"The low block and the counter-attack: Overview","terms":"The low block and the counter-attack","content":"A low block is a deep, narrow defensive shape: two lines close together near the team's own box, conceding possession and territory to deny space in behind and between the lines."}]
{"kind":"reference","ref_id":0,"uri":"https://matchdesk-search-amgcx4ym3b4s6.search.windows.net/indexes/matchdesk-knowledge/docs/concepts-physical-data-definitions-used-by-match-desk?$select=title%2Ccontent%2Cpage%2Cid%2Ccategory\u0026api-version=2026-08-01-preview\u0026allowUnsafeKeys=true","mimeType":"application/json","sourceData":{"id":"concepts-physical-data-definitions-used-by-match-desk","title":"Physical data: sprints, speed, and distance: Definitions used by Match Desk","page":"Physical data: sprints, speed, and distance","category":"concept","content":"- A sprint is running faster than 25.2 km/h for at least one second.\n- Top speed is the fastest a player reached during a sprint; elite players reach 33 to 36 km/h.\n- Distance covered is the total ground a player has run. A typical outfield player covers 10 to 12 km in a match; midfielders usually cover the most."}}
{"kind":"reference","ref_id":1,"uri":"https://matchdesk-search-amgcx4ym3b4s6.search.windows.net/indexes/matchdesk-knowledge/docs/concepts-low-block-and-counter-counter-attacking?$select=title%2Ccontent%2Cpage%2Cid%2Ccategory\u0026api-version=2026-08-01-preview\u0026allowUnsafeKeys=true","mimeType":"application/json","sourceData":{"id":"concepts-low-block-and-counter-counter-attacking","title":"The low block and the counter-attack: Counter-attacking","page":"The low block and the counter-attack","category":"concept","content":"Teams that sit in a low block aim to break quickly when they win the ball, with forwards who run into the space the opponent leaves behind. The danger is in the transition, not in long spells of possession."}}
